import{_ as e,C as s,c as l,o as h,aa as o,G as a}from"./chunks/framework.Cn7WEiMX.js";const u=JSON.parse('{"title":"设置自定义光照","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Dynmap/advanced-configuration/advanced-map-configuration/defining-custom-lightings.md","filePath":"wiki/Dynmap/advanced-configuration/advanced-map-configuration/defining-custom-lightings.md"}'),p={name:"wiki/Dynmap/advanced-configuration/advanced-map-configuration/defining-custom-lightings.md"};function d(g,i,c,k,r,E){const n=s("NolebaseGitContributors"),t=s("NolebaseGitChangelog");return h(),l("div",null,[i[0]||(i[0]=o(`<h1 id="设置自定义光照" tabindex="-1">设置自定义光照 <a class="header-anchor" href="#设置自定义光照" aria-label="Permalink to &quot;设置自定义光照&quot;">​</a></h1> <p>自定义光照可通过修改 <code>lightings.txt</code> 的标准光照设置或在 <code>custom-lightings.txt</code> 文件中新增/更新内容实现（推荐后者）。</p> <p>目前只有两种光照类型——DefaultHDLighting 与 ShadowHDLighting。</p> <p>DefaultHDLighting 不修改阴影的颜色数据——实际显示与无阴影白天地图等同，且没有设置。</p> <p>ShadowHDLighting 有一些设置项，允许控制自然光照、阴影强度及是否为同一张地图生成白天与夜间样式的图块。</p> <p>标准的光照配置示例如下：</p> <div class="language-YAML vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">lightings</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">org.dynmap.hdmap.ShadowHDLighting</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">my-custom-lighting</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    shadowstrength</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    ambientlight</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    night-and-day</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    smooth-lighting</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><p>这些 ShadowHDLighting 类的设置详细解释如下：</p> <ul><li><code>name</code>：光照定义的名称，不可重复。若 custom-lightings.txt 中有自定义光照与标准光照定义中的名称重合，那么对应的标准光照将会被自定义光照设置覆盖。</li> <li><code>shadowstrength</code>：决定了阴影区域的强度。默认为 0.0（不渲染阴影），正常阴影为 1.0。大于 1.0 的值会让阴影更加浓重，反之则让阴影更淡。</li> <li><code>ambientlight</code>：决定了自然光照的相对量。完整自然光照为 15（也是默认值），夜间自然光照则为 4。</li> <li><code>night-and-day</code>：启用此设置（调为 <code>true</code>）后，会为每个图块生成白天与夜间的版本，会在地图浏览器中根据世界时间自动切换。“夜间”与“白天”图块的差别在于，白天图块样貌类似于 <code>ambientlight</code> 设置为 15 时的结果，而夜间则跟随上述设置。默认值为 <code>false</code>。</li> <li><code>smooth-lighting</code>：决定了是否启用平滑光照功能。启用后会增加约 10% 的处理开销，但会使得阴影与光照更柔和。若未设置，则使用 configuration.txt 中设置的值。</li></ul> `,17)),a(n),a(t)])}const y=e(p,[["render",d]]);export{u as __pageData,y as default};
